(ns fastmath.signal.biquad-test
  (:require [fastmath.signal.biquad :as sut]
            [clojure.test :as t]
            [clojure.java.io :as io]
            [clojure.edn :as edn])
  (:import [fastmath.signal.biquad BiquadConf]))

;; Reference coefficients written independently from the Audio EQ Cookbook, generated by
;; `utils/fastmath/dev/generate_biquad_reference.py` into `test/resources/signal/biquad_reference.edn`:
;; 8 filter types, fs 44100, 48000, 1; fc from 0.001 fs to 0.45 fs; bandwidths, gains, shelf Q.

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "signal/biquad_reference.edn")))))

(defn- conf->vec [^BiquadConf c] [(.b0 c) (.b1 c) (.b2 c) (.a0 c) (.a1 c) (.a2 c)])

(defn- close?
  "Same formulas evaluated in a different order: 1e-14 relative to the largest coefficient
  (shelf a0 reaches ~5)."
  [a b]
  (let [scale (inc (reduce max (map #(Math/abs (double %)) a)))]
    (every? (fn [[x y]] (<= (Math/abs (- (double x) (double y))) (* 1.0e-14 scale))) (map vector a b))))

(t/deftest coefficients-vs-cookbook
  (doseq [{:keys [kind fc fs bw gain Q coeffs]} (:filters @reference)
          :let [res (case kind
                      :lowpass (sut/lowpass fc bw fs)
                      :highpass (sut/highpass fc bw fs)
                      :bandpass (sut/bandpass fc bw fs)
                      :notch (sut/notch fc bw fs)
                      :allpass (sut/allpass fc bw fs)
                      :equalizer (sut/equalizer fc gain bw fs)
                      :lowshelf (sut/lowshelf fc gain Q fs)
                      :highshelf (sut/highshelf fc gain Q fs))]]
    (t/is (close? coeffs (conf->vec res)) (str kind " fc=" fc " fs=" fs " bw=" bw " gain=" gain " Q=" Q))))

(t/deftest conversions
  (t/testing "digital bandwidth: alpha at fc 1 kHz, fs 44.1 kHz, 1 octave"
    (let [w0 (* 2 Math/PI (/ 1000.0 44100.0))]
      (t/is (< (Math/abs (- 0.050379619599263514 (/ (Math/sin w0) (* 2.0 (sut/bandwidth->Q 1.0 1000.0 44100.0))))) 1e-17))))
  (t/testing "analog form"
    (t/is (< (Math/abs (- (/ 1.0 (* 2.0 (Math/sinh (* 0.5 (Math/log 2.0)))) ) (sut/bandwidth->Q 1.0))) 1e-15))
    (t/is (< (Math/abs (- (Math/sqrt 0.5) (sut/bandwidth->Q 1.8999686269529916))) 1e-12) "Q of a Butterworth section"))
  (t/testing "round trips"
    (doseq [bw [0.1 1.0 3.0]]
      (t/is (< (Math/abs (- bw (sut/Q->bandwidth (sut/bandwidth->Q bw)))) 1e-14))
      (t/is (< (Math/abs (- bw (sut/Q->bandwidth (sut/bandwidth->Q bw 3000.0 44100.0) 3000.0 44100.0))) 1e-14))))
  (t/testing "shelf slope"
    (doseq [{:keys [gain S Q]} (:slopes @reference)]
      (t/is (< (Math/abs (- Q (sut/shelf-slope->Q gain S))) 1e-15) (str gain " " S)))
    (t/is (< (Math/abs (- (Math/sqrt 0.5) (sut/shelf-slope->Q 0.0 1.0))) 1e-15) "S = 1 gives Q = 1/sqrt(2)")))

(t/deftest guards
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/lowpass 0.0 1.0 44100.0)) "fc = 0")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/lowpass 22050.0 1.0 44100.0)) "fc = fs/2")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/lowpass -10.0 1.0 44100.0)))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/lowpass 100.0 1.0 0.0)) "fs = 0")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/bandpass 100.0 0.0 44100.0)) "bw = 0")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/equalizer 100.0 3.0 -1.0 44100.0)))
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/highshelf 100.0 3.0 0.0 44100.0)) "Q = 0")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/shelf-slope->Q 6.0 0.0)) "S = 0")
  (t/is (thrown? clojure.lang.ExceptionInfo (sut/shelf-slope->Q 12.0 10.0)) "S too large")
  (t/is (some? (sut/lowpass 22049.0 1.0 44100.0)) "just below Nyquist"))
